import io.netty.bootstrap.ServerBootstrap;
import io.netty.channel.*;
import io.netty.channel.epoll.*;
import io.netty.handler.timeout.IdleStateHandler;
import io.netty.util.concurrent.*;
import java.util.concurrent.*;

public class StarvationSafeGateway {
    public static void start() throws InterruptedException {
        EventLoopGroup boss = new EpollEventLoopGroup(1);
        EventLoopGroup workers = new EpollEventLoopGroup(8);
        EventExecutorGroup heavyPool = new DefaultEventExecutorGroup(32);

        startLoopWatchdog(workers, 10_000_000L); // 10 ms threshold

        new ServerBootstrap()
            .group(boss, workers)
            .channel(EpollServerSocketChannel.class)
            .childOption(ChannelOption.MAX_MESSAGES_PER_READ, 16)
            .childOption(ChannelOption.WRITE_BUFFER_WATER_MARK,
                         new WriteBufferWaterMark(32 * 1024, 64 * 1024))
            .childHandler(new ChannelInitializer<Channel>() {
                @Override
                protected void initChannel(Channel ch) {
                    ch.pipeline()
                      .addLast(new IdleStateHandler(60, 0, 0))
                      .addLast(heavyPool, new HeavyJsonHandler());
                }
            })
            .bind(8443).sync();
    }

    private static void startLoopWatchdog(EventLoopGroup group, long maxLagNs) {
        ScheduledExecutorService watchdog = Executors.newSingleThreadScheduledExecutor();
        watchdog.scheduleAtFixedRate(() -> {
            for (EventExecutor loop : group) {
                long scheduledNs = System.nanoTime();
                loop.execute(() -> {
                    long lag = System.nanoTime() - scheduledNs;
                    if (lag > maxLagNs) {
                        System.err.printf("EventLoop %s stalled %.2f ms%n",
                            Thread.currentThread().getName(), lag / 1e6);
                    }
                });
            }
        }, 5, 5, TimeUnit.MILLISECONDS);
    }
}

// Backpressure toggle when outbound buffer exceeds 64 KB
@Override
public void channelWritabilityChanged(ChannelHandlerContext ctx) {
    upstreamChannel.config().setAutoRead(ctx.channel().isWritable());
    ctx.fireChannelWritabilityChanged();
}
